<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\Snippet\Application\Usecase\Enable;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\Snippet\Domain\SnippetRef;
use Civi\Lughauth\Features\Document\Snippet\Application\Service\Visibility\SnippetVisibilityService;
use Civi\Lughauth\Features\Document\Snippet\Domain\Gateway\SnippetWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class SnippetEnableUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly SnippetVisibilityService $visibility,
        private readonly SnippetWriteGateway $writer,
    ) {
    }

    public function allowEnable(?SnippetRef $ref = null): Allow
    {
        $this->logDebug("Check allow of Enable usecase for Snippet");
        $span = $this->startSpan("Check allow of Enable usecase for Snippet");
        try {
            $result = $this->dispatcher->dispatch(new SnippetEnableAllowDecision(Allow::allowed('enable', 'Allowed to Snippet by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function enable(string $uid): SnippetEnableResult
    {
        $this->logDebug("Run Enable usecase for Snippet");
        $span = $this->startSpan("Run Enable usecase for Snippet");
        try {
            $ref = new SnippetRef($uid);
            $allow = $this->allowEnable($ref);
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to Enable Snippet');
            }
            if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
                throw new NotFoundException($uid);
            }
            $this->dispatcher->dispatch(new SnippetEnableCheck($original));
            $modified = $original->enable();
            $result = $this->writer->update($original, $modified);
            $output = $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($result));
            return new SnippetEnableResult($output);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
